Here is the commit message:
tipc: fix a possible memleak in tipc_buf_append

__skb_linearize() doesn't free the skb when it fails, so move
'*buf = NULL' after __skb_linearize(), so that the skb can be
freed on the err path.

Fixes: b7df21cf1b79 ("tipc: skb_linearize the head skb when reassembling msgs")
Reported-by: Paolo Abeni <pabeni@redhat.com>
Signed-off-by: Xin Long <lucien.xin@gmail.com>
Reviewed-by: Simon Horman <horms@kernel.org>
Reviewed-by: Tung Nguyen <tung.q.nguyen@dektech.com.au>
Link: https://lore.kernel.org/r/90710748c29a1521efac4f75ea01b3b7e61414cf.1714485818.git.lucien.xin@gmail.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug arises because the function `__skb_linearize()` does not free the socket buffer (`skb`) when it fails. As a result, if the linearization fails and the pointer `*buf` is set to `NULL` before the linearization attempt, the reference to the `skb` is lost, leading to a memory leak since the `skb` cannot be freed properly.

Here is the patch:
  */
 int tipc_buf_append(struct sk_buff **headbuf, struct sk_buff **buf)
 {
 	struct sk_buff *head = *headbuf;
 	struct sk_buff *frag = *buf;
 	struct sk_buff *tail = NULL;
 	struct tipc_msg *msg;
 	u32 fragid;
 	int delta;
 	bool headstolen;

 	if (!frag)
 		goto err;

 	msg = buf_msg(frag);
 	fragid = msg_type(msg);
 	frag->next = NULL;
 	skb_pull(frag, msg_hdr_sz(msg));

 	if (fragid == FIRST_FRAGMENT) {
 		if (unlikely(head))
 			goto err;
-		*buf = NULL;
 		if (skb_has_frag_list(frag) && __skb_linearize(frag))
 			goto err;
+		*buf = NULL;
 		frag = skb_unshare(frag, GFP_ATOMIC);
 		if (unlikely(!frag))
 			goto err;
 		head = *headbuf = frag;
 		TIPC_SKB_CB(head)->tail = NULL;
 		return 0;
 	}

 	if (!head)
 		goto err;

 	/* Either the input skb ownership is transferred to headskb
 	 * or the input skb is freed, clear the reference to avoid
 	 * bad access on error path.
 	 */
 	*buf = NULL;
 	if (skb_try_coalesce(head, frag, &headstolen, &delta)) {
 		kfree_skb_partial(frag, headstolen);
 	} else {
 		tail = TIPC_SKB_CB(head)->tail;
 		if (!skb_has_frag_list(head))
 			skb_shinfo(head)->frag_list = frag;
 		else
 			tail->next = frag;
 		head->truesize += frag->truesize;
 		head->data_len += frag->len;
 		head->len += frag->len;
 		TIPC_SKB_CB(head)->tail = frag;
 	}

 	if (fragid == LAST_FRAGMENT) {
 		TIPC_SKB_CB(head)->validated = 0;
 		if (unlikely(!tipc_msg_validate(&head)))
 			goto err;
 		*buf = head;
 		TIPC_SKB_CB(head)->tail = NULL;
 		*headbuf = NULL;
 		return 1;
 	}
 	return 0;
 err:
 	kfree_skb(*buf);
 	kfree_skb(*headbuf);
 	*buf = *headbuf = NULL;
 	return 0;
 }



